def expected_score(n, k):
    from functools import lru_cache

    @lru_cache(None)
    def E(n, k):
        if k == 1:
            return (1 + n) / 2
        else:
            return (E(n, k-1) + sum(max(i, E(n, k-1)) for i in range(1, n+1))) / n

    return E(n, k)

# Read input
import sys
input = sys.stdin.read
data = input().split()
n = int(data[0])
k = int(data[1])

# Calculate and print the expected score
print(expected_score(n, k))
